
import type { DeliveryProfileOriginPolicy } from './DeliveryProfileOriginPolicy.js';
import type { Dimensions } from './Dimensions.js';
import type { Weight } from './Weight.js';

export type DeliveryProfileConfiguration = { /** Required as a non-empty unique list when requirement is required. quote accepts shipment, pickup, and local_delivery. manual accepts digital and service. */ "allowed_types"?: Array<"shipment" | "pickup" | "local_delivery" | "digital" | "service" | (string & {})>; /** Required for quote resolution and forbidden when requirement is none or resolution_mode is manual. Controls which delivery obligations can share a choice group. */ "combination_policy"?: "combine_when_compatible" | "separate_profile" | "separate_line_item" | "fulfill_alone" | (string & {}); /** Optional physical dimensions used by quote planning. Forbidden when requirement is none or resolution_mode is manual. */ "dimensions"?: Dimensions; /** Required for quote resolution and forbidden for none or manual resolution. fixed_location requires location_id. inventory_routing forbids location_id and applies only to tracked inventory. method_origin forbids location_id. */ "origin_policy"?: DeliveryProfileOriginPolicy; /** Whether delivery planning applies. none forbids every other configuration field. required also requires resolution_mode and allowed_types, plus the fields required by that resolution mode. */ "requirement": "none" | "required" | (string & {}); /** Required when requirement is required. quote plans physical delivery and requires origin_policy, combination_policy, and splitting_policy. manual supports digital and service items and forbids physical planning fields. */ "resolution_mode"?: "quote" | "manual" | (string & {}); /** Required for quote resolution and forbidden when requirement is none or resolution_mode is manual. Controls whether a line item quantity can be split across delivery assignments. */ "splitting_policy"?: "whole_line_item" | "quantity_split_allowed" | (string & {}); /** Optional physical weight used by quote planning. Forbidden when requirement is none or resolution_mode is manual. */ "weight"?: Weight; };
